/// <summary>
/// Extension of class <c>CustAccountStatementExtController</c>
/// </summary>
[ExtensionOf(classStr(CustAccountStatementExtController))]
final class KPMGCustAccountStatementExtController_Extension
{
    private Map custLogoMap;    // <CustAccount, Image data>
    private boolean     kpmgPrintNegative; 

}

Method.Source:
    /// <summary>
    /// Sets company information, logo and other common report header information to <c>CustAccountStatementExtTmp</c> table buffer.
    /// </summary>
    protected void setCommonData()
    {
        next setCommonData();
        custAccountStatementExtTmp.KPMGCompanyEmail = statementCompanyInfo.email();

        // MPJ_4044_CustomerAccountStatement - kscerri - 21/07/2021 - Start
        // Footer company bank info
        custAccountStatementExtTmp.KPMGRegNum           = BankAccountTable::find(statementCompanyInfo.Bank).RegistrationNum;
        custAccountStatementExtTmp.KPMGBankAccountNum   = BankAccountTable::find(statementCompanyInfo.Bank).AccountNum;
        custAccountStatementExtTmp.KPMGRemittanceEmail  = this.getStatement(statementCompanyInfo, LogisticsElectronicAddressMethodType::Email);
        custAccountStatementExtTmp.KPMGCustServiceNum   = this.getStatement(statementCompanyInfo, LogisticsElectronicAddressMethodType::Phone);
        custAccountStatementExtTmp.KPMGFooterNote       = this.parmContract().parmFooterNote();
        METIndustryKeyTable  metIndustryKeyTable = METIndustryKeyTable::find(METCustTable::find(currentCust.accountNum).IndustryKey);
        if (metIndustryKeyTable)
        {
            if (metIndustryKeyTable.CoRegNum)
            {
                custAccountStatementExtTmp.CompanyCoRegNum = metIndustryKeyTable.CoRegNum;
            }
            if (metIndustryKeyTable.CompanyName)
            {
                custAccountStatementExtTmp.CompanyName = metIndustryKeyTable.CompanyName;
            }
            if (metIndustryKeyTable.StatementFooterNote)
            {
                custAccountStatementExtTmp.KPMGFooterNote = metIndustryKeyTable.StatementFooterNote;
            }
        }
        // MPJ_4044_CustomerAccountStatement - kscerri - 21/07/2021 - End

        this.metSetLogo();  // MPJ-13531
    }

    /// <summary>
    /// Set logo based on customer settings.
    /// </summary>
    private void metSetLogo()
    {
        if(!custLogoMap)
            custLogoMap = new Map(Types::String, Types::Container);

        container imgData;
        if(custLogoMap.exists(custAccountStatementExtTmp.AccountNum))
        {
            imgData = custLogoMap.lookup(custAccountStatementExtTmp.AccountNum);
        }
        else
        {
            Image img = CustTable::metGetCustReportLogo(custAccountStatementExtTmp.AccountNum);
            if(img != null)
            {
                imgData = img.getData();
            }
            custLogoMap.insert(custAccountStatementExtTmp.AccountNum, imgData);
        }
        if(conLen(imgData) > 0)
        {
            custAccountStatementExtTmp.CompanyLogo = imgData;
            custAccountStatementExtTmp.PrintLogo   = true;
        }
    }

    /// <summary>
    /// MPJ_4044_CustomerAccountStatement - kscerri - 21/07/2021
    /// Footer BPay info
    /// </summary>
    /// <param name = "_custCurrencyIndex">The customer currency index</param>
    protected void populateCustAccountStatementExtTmp(int _custCurrencyIndex)
    {
        METCustTable metCustTable;

        next populateCustAccountStatementExtTmp(_custCurrencyIndex);

        if (custPre)
        {
            metCustTable = METCustTable::find(currentCust.accountNum);
            custAccountStatementExtTmp.KPMGBPayBillerCode   = metCustTable.BPayBillerCode;
            custAccountStatementExtTmp.KPMGBPayReference    = metCustTable.BPayReference;
            custAccountStatementExtTmp.KPMGKnownAs          = DirPartyTable::findRec(currentCust.party).KnownAs;
            custAccountStatementExtTmp.KPMGBsbReference     = metCustTable.BsbReference;
            custAccountStatementExtTmp.KPMGCurrency         = currentCust.currency;
            custAccountStatementExtTmp.KPMGIndustryKey      = metCustTable.IndustryKey;
            
        }

    }

    /// <summary>
    /// MPJ_4044_CustomerAccountStatement - kscerri - 22/07/2021
    /// </summary>
    /// <param name = "_companyInfo">Company info record</param>
    /// <param name = "_Type">pick remit to type email or phone</param>
    /// <returns>email or phone details</returns>
    public LogisticsElectronicAddressLocator getStatement(CompanyInfo _companyInfo, LogisticsElectronicAddressMethodType _Type)
    {        
        DirPartyLocation            dirPartyLocation;
        LogisticsElectronicAddress  logisticsElectronicAddress;
        str remitTo = strFmt("*%1*",enum2Str(LogisticsLocationRoleType::RemitTo));

        select firstonly Locator from  logisticsElectronicAddress
            exists join dirPartyLocation
                where logisticsElectronicAddress.location               == dirPartyLocation.location
                   && dirPartyLocation.Party                            == _companyInfo.RecId
                   && logisticsElectronicAddress.type                   == _Type
                   && logisticsElectronicAddress.ElectronicAddressRoles like remitTo;
               
        return logisticsElectronicAddress.Locator;
    }

    /// <summary>
    /// Determines whether a customer will be on the statement.
    /// </summary>
    /// <param name = "_custTable">
    /// The customer record to be checked.
    /// </param>
    /// <returns>
    /// true if a customer will be on the statement; otherwise, false.
    /// </returns>
    protected boolean hasCustomerStatement(CustTable _custTable)
    {
        AmountMST   metBalance = _custTable.balancePerDate(statementEndDate);

        boolean  ret = next hasCustomerStatement(_custTable);

        ret = ret && ((metBalance < 0 && kpmgPrintNegative) || (metBalance > 0));

        return ret;

    }

    /// <summary>
    ///    Runs the print report.
    /// </summary>
    protected void runPrintMgmt()
    {
        kpmgPrintNegative =  this.parmContract().kpmgParmPrintnegative();

        next runPrintMgmt();
    }
